const allowedStatuses = new Set(["backlog", "planned", "in_progress", "blocked", "shipped"]);
const allowedPriorities = new Set(["urgent", "high", "medium", "low"]);

// Loop One is the only active milestone. It is the shortest closed circuit that
// proves the Revenue OS actually works: one real inquiry is captured, resolved to
// a canonical identity, becomes an opportunity, surfaces in Today with a stated
// reason, receives a tracked reply, generates exactly one follow-up commitment,
// and is counted in source-to-revenue attribution.
//
// Order is the intended execution order. Cards earn their place here by being on
// that circuit, not by being important in the abstract — nearly every card on this
// board is important, which is precisely why the board stopped functioning as a
// queue. Promote a card by adding its key; demote by removing it.
const LOOP_ONE = [
  "identity-resolution-service",
  "activity-ledger-normalization",
  "task-dedup-service",
  "priority-selector-service",
  "today-operator-inbox",
  "communication-sender-service",
  "pipeline-stage-board",
  "canonical-attribution",
  "tenant-config-seam",
];
const LOOP_ONE_SET = new Set(LOOP_ONE);

// Everything outside Loop One keeps its full specification but is shelved behind a
// `horizon` label, which the board filters out by default. Shelving is not
// deletion and not a judgement about value; it is a statement that the card is not
// on the current circuit. Nothing here is claimed until someone claims it, so no
// card ships as in_progress from the manifest.
function card({ key, title, workstream, phase, status = "backlog", priority = "medium", description, acceptance, dependencies = [], start, guardrails, owner = null, labels = [], evidence = null, verification = null }) {
  const effectiveStatus = status;
  const isLoopOne = LOOP_ONE_SET.has(key);
  const shelved = effectiveStatus !== "shipped" && !isLoopOne;
  if (!allowedStatuses.has(effectiveStatus)) throw new Error(`Invalid status for ${key}`);
  if (!allowedPriorities.has(priority)) throw new Error(`Invalid priority for ${key}`);
  if (isLoopOne && effectiveStatus === "backlog") throw new Error(`Loop One card ${key} must be planned or further along`);
  return {
    seed_key: key,
    title,
    description,
    status: effectiveStatus,
    priority,
    labels: [
      "revenue-os",
      "agent-ready",
      `phase-${phase}`,
      workstream,
      ...(isLoopOne ? ["loop-one", `loop-step-${LOOP_ONE.indexOf(key) + 1}`] : []),
      ...(shelved ? ["horizon"] : []),
      ...labels,
    ],
    owner,
    target_date: null,
    acceptance_criteria: acceptance.map((item) => `- ${item}`).join("\n"),
    notes: [
      `Workstream: ${workstream}. Phase: ${phase}.`,
      `Dependencies: ${dependencies.length ? dependencies.join("; ") : "None — this can be claimed immediately."}`,
      `Starting points: ${start}`,
      `Guardrails / non-goals: ${guardrails}`,
      isLoopOne
        ? `Milestone: Loop One, step ${LOOP_ONE.indexOf(key) + 1} of ${LOOP_ONE.length}. Loop One is the active milestone — one real inquiry captured, resolved, surfaced in Today, replied to with a receipt, and attributed to revenue. Claim this card by setting Owner and in_progress; keep no more than two cards in progress at once.`
        : shelved
          ? "Milestone: horizon. This card keeps its full specification but is not on the current Loop One circuit and is filtered out of the default board. Do not start it before the Loop One cards unless a Loop One card explicitly depends on it."
          : "Milestone: closed. This card is shipped; reopen it only with new evidence that an acceptance item no longer holds.",
      "Architecture contract: docs/REVENUE-OS-ENGINEERING-CONTRACT.md. Agent procedure: docs/AGENT-TICKET-RUNBOOK.md. Module ownership: src/lib/revenue-os/README.md.",
      `Required verification: ${verification || "npm run verify:agent-contract; npx tsc --noEmit; npm run lint; the closest scoped service/API/Playwright test named by this card; npm run build and git diff --check before Shipped. Data or automation changes must also prove invalid input, duplicate/replay, truthful failure receipts, and safe retry. UI changes require reviewed desktop/mobile screenshots."}`,
      "Stop conditions: pause and create or update a dependency card before adding a new provider, weakening authorization, performing a destructive migration, expanding real-recipient automation, or bypassing an authoritative domain service.",
      ...(evidence ? [`Current implementation evidence: ${evidence}`] : []),
      "Agent handoff: claim the card by setting Owner, read linked services and migrations before editing, preserve unrelated worktree changes, attach test evidence in Internal notes, and move to Shipped only after every acceptance item is verified.",
    ].join("\n\n"),
    source: "revenue-os-master-plan",
    archived_at: null,
  };
}

